begin;
insert into auth.users(id,raw_user_meta_data) values ('ee510000-0000-4000-8000-000000000001','{}'),('ee510000-0000-4000-8000-000000000002','{}') on conflict do nothing;
alter table profiles disable trigger guard_profile_privileges;
update profiles set role='OWNER',is_active=true where id='ee510000-0000-4000-8000-000000000001'; update profiles set role='FINANCE',is_active=true where id='ee510000-0000-4000-8000-000000000002'; alter table profiles enable trigger guard_profile_privileges;
insert into branches(id,code,name,type) values('ee520000-0000-4000-8000-000000000001','CT','Cash test','PETSHOP') on conflict do nothing;
insert into coa_accounts(code,name,type,normal_balance,is_active) values('1101','Cash test','ASET','D',true),('4101','Income test','PENDAPATAN','K',true) on conflict(code) do update set is_active=true;
insert into cash_accounts(id,nama,jenis,coa_code) select 'ee560000-0000-4000-8000-000000000001','Cash test','Kas',code from coa_accounts where code='1101' on conflict do nothing;
insert into user_branches(user_id,branch_id) values('ee510000-0000-4000-8000-000000000001','ee520000-0000-4000-8000-000000000001'),('ee510000-0000-4000-8000-000000000002','ee520000-0000-4000-8000-000000000001') on conflict do nothing;
create function pg_temp.assert_true(v boolean,l text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'ASSERT: %',l;end if;end$$;
create function pg_temp.expect_error(s text,f text) returns void language plpgsql as $$begin begin execute s;raise exception 'expected failure';exception when others then if position(f in sqlerrm)=0 then raise;end if;end;end$$;
update accounting_locks set closed_until=null where id; grant usage on schema auth to authenticated; grant execute on function auth.uid() to authenticated; grant usage on schema public to authenticated; set local role authenticated; select set_config('request.jwt.claim.sub','ee510000-0000-4000-8000-000000000002',true); select set_config('request.jwt.claim.role','authenticated',true);
insert into cash_entries(id,no_bukti,jenis,tanggal,account_id,lawan_code,jumlah,branch_id,created_by) values('ee530000-0000-4000-8000-000000000001','KM.TEST.001','Masuk',current_date-1,(select id from cash_accounts limit 1),(select code from coa_accounts where code not in(select coa_code from cash_accounts) and is_active limit 1),100,'ee520000-0000-4000-8000-000000000001',auth.uid());
insert into journal_entries(id,no_jurnal,tanggal,deskripsi,source,source_ref,branch_id) values('ee540000-0000-4000-8000-000000000001','JRN-CT-001',current_date-1,'Cash test','kas-entry','KM.TEST.001','ee520000-0000-4000-8000-000000000001');
insert into journal_lines(entry_id,account_id,debit,credit) select 'ee540000-0000-4000-8000-000000000001',a.id,case when a.code=(select coa_code from cash_accounts limit 1) then 100 else 0 end,case when a.code=(select lawan_code from cash_entries where id='ee530000-0000-4000-8000-000000000001') then 100 else 0 end from coa_accounts a where a.code in((select coa_code from cash_accounts limit 1),(select lawan_code from cash_entries where id='ee530000-0000-4000-8000-000000000001'));
select pg_temp.expect_error($q$update cash_entries set revision=9 where id='ee530000-0000-4000-8000-000000000001'$q$,'Metadata koreksi');
select pg_temp.expect_error($q$update cash_entries set no_bukti='KM.OTHER.001' where id='ee530000-0000-4000-8000-000000000001'$q$,'Metadata koreksi');
select pg_temp.expect_error($q$update cash_entries set journal_entry_id='ee540000-0000-4000-8000-000000000001' where id='ee530000-0000-4000-8000-000000000001'$q$,'Metadata koreksi');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.cash_entry_revision_requests','SELECT'),'posting requests stay private');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.cash_entry_revisions','INSERT'),'audit cannot be forged');
select pg_temp.expect_error($q$update journal_entries set voided_at=now() where id='ee540000-0000-4000-8000-000000000001'$q$,'Metadata koreksi');
select pg_temp.expect_error($q$select revise_cash_entry('null-action','ee530000-0000-4000-8000-000000000001',0,null,'{}','reason')$q$,'tidak valid');
select pg_temp.expect_error(format('select revise_cash_entry(%L,%L,0,%L,%L,%L)','nope','ee530000-0000-4000-8000-000000000001','edit','{}','reason'),'Super Admin');
select set_config('request.jwt.claim.sub','ee510000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((revise_cash_entry('edit-ok','ee530000-0000-4000-8000-000000000001',0,'edit',jsonb_build_object('jumlah',125,'keterangan','Corrected'),'Correction')->>'replacement_journal_id') is not null,'edit creates replacement');
select pg_temp.assert_true((revise_cash_entry('edit-ok','ee530000-0000-4000-8000-000000000001',0,'edit',jsonb_build_object('jumlah',125,'keterangan','Corrected'),'Correction')->>'replacement_journal_id') is not null,'edit retry confirms original result');
select pg_temp.assert_true((select count(*)=1 from cash_entry_revisions where cash_entry_id='ee530000-0000-4000-8000-000000000001'),'retry does not add reversal');
select pg_temp.expect_error($q$select revise_cash_entry('edit-ok','ee530000-0000-4000-8000-000000000001',0,'edit','{"jumlah":126,"keterangan":"Corrected"}','Correction')$q$,'rincian berbeda');
reset role;
insert into branches(id,code,name,type) values('ee520000-0000-4000-8000-000000000002','CT-B','Cash test B','PETSHOP');
insert into coa_accounts(code,name,type,normal_balance,is_active) values('1199','Other branch cash','ASET','D',true);
insert into cash_accounts(id,nama,jenis,coa_code,branch_id) values('ee560000-0000-4000-8000-000000000002','Other branch cash','Kas','1199','ee520000-0000-4000-8000-000000000002');
set local role authenticated;
select pg_temp.expect_error($q$select revise_cash_entry('foreign-account','ee530000-0000-4000-8000-000000000001',1,'edit','{"account_id":"ee560000-0000-4000-8000-000000000002"}','Correction')$q$,'di luar cabang');
select pg_temp.expect_error($q$select revise_cash_entry('fractional','ee530000-0000-4000-8000-000000000001',1,'edit','{"jumlah":125.123}','Correction')$q$,'tidak valid');
reset role;
update cash_accounts set is_active=false where id=(select account_id from cash_entries where id='ee530000-0000-4000-8000-000000000001');
update coa_accounts set is_active=false where code=(select lawan_code from cash_entries where id='ee530000-0000-4000-8000-000000000001');
set local role authenticated;
select set_config('request.jwt.claim.sub','ee510000-0000-4000-8000-000000000002',true);
select pg_temp.expect_error(format('select revise_cash_entry(%L,%L,0,%L,%L,%L)','stale','ee530000-0000-4000-8000-000000000001','void','{}','reason'),'berubah');
select revise_cash_entry('void-ok','ee530000-0000-4000-8000-000000000001',1,'void','{}','Cancel correction'); select pg_temp.assert_true((select voided_at is not null from cash_entries where id='ee530000-0000-4000-8000-000000000001'),'void marks cash');
select pg_temp.assert_true((select sum(l.debit)=sum(l.credit) and sum(l.debit-l.credit)=0 from journal_lines l join journal_entries j on j.id=l.entry_id where j.source in ('kas-entry','kas-entry-correction','kas-entry-reversal')),'edit and void retain balanced journals');
select pg_temp.assert_true((select sum(l.debit-l.credit)=0 from journal_lines l join journal_entries j on j.id=l.entry_id join coa_accounts a on a.id=l.account_id where a.code='1101' and j.source in ('kas-entry','kas-entry-correction','kas-entry-reversal')),'cash balance returns to zero');
select revise_cash_entry('void-ok','ee530000-0000-4000-8000-000000000001',1,'void','{}','Cancel correction');
select pg_temp.assert_true((select count(*)=2 from cash_entry_revisions where cash_entry_id='ee530000-0000-4000-8000-000000000001'),'void retry does not duplicate reversal');
reset role;
insert into cash_entries(id,no_bukti,jenis,tanggal,account_id,lawan_code,jumlah,branch_id,created_by)
select 'ee530000-0000-4000-8000-000000000002','KM.TEST.002','Masuk',current_date-1,account_id,lawan_code,100,branch_id,created_by from cash_entries where id='ee530000-0000-4000-8000-000000000001';
insert into journal_entries(id,no_jurnal,tanggal,deskripsi,source,source_ref,branch_id) values('ee540000-0000-4000-8000-000000000002','JRN-CT-002',current_date-1,'Wrong branch','kas-entry','KM.TEST.002','ee520000-0000-4000-8000-000000000002');
insert into journal_lines(entry_id,account_id,debit,credit) select 'ee540000-0000-4000-8000-000000000002',account_id,debit,credit from journal_lines where entry_id='ee540000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.expect_error($q$select revise_cash_entry('mismatch-branch','ee530000-0000-4000-8000-000000000002',0,'void','{}','Correction')$q$,'cabang atau tanggal');
reset role;
update journal_entries set branch_id='ee520000-0000-4000-8000-000000000001',tanggal=current_date-2 where id='ee540000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.expect_error($q$select revise_cash_entry('mismatch-date','ee530000-0000-4000-8000-000000000002',0,'void','{}','Correction')$q$,'cabang atau tanggal');
rollback;
